        "since"
      ],
      "feedback": "Use \"for\" quando mede a duração total de um evento."
    },
    {
      "sentence": "He has worked at the bank ___ 2018.",
      "answer": "since",
      "translation": "Ele trabalha no banco desde 2018.",
      "options": [
        "for",
        "since"
