      "answer": "está",
      "translation": "The coffee is hot.",
      "options": [
        "es",
        "está"
      ],
      "feedback": "Use \"está\" because being hot is a temporary condition for the coffee."
    },
    {
      "sentence": "Mateo ___ un buen estudiante.",
      "answer": "es",
      "translation": "Mateo is a good student.",
      "options": [
        "es",
        "está"
      ],
      "feedback": "Use \"es\" because being a student describes his identity and permanent role."
    },
    {
      "sentence": "Mis llaves ___ en la mesa.",
      "answer": "están",
      "translation": "My keys are on the table.",
      "options": [
        "son",
        "están"
      ],
      "feedback": "Use \"están\" because you are telling the current location of the keys."
    },
    {
      "sentence": "El obelisco ___ en el centro de la ciudad.",
      "answer": "está",
      "translation": "The obelisk is in the center of the city.",
      "options": [
        "es",
        "está"
      ],
      "feedback": "Use \"está\" because it describes the fixed location of a landmark."
    },
    {
      "sentence": "Sofía ___ muy simpática.",
      "answer": "es",
      "translation": "Sofía is very nice.",
      "options": [
        "es",
        "está"
      ],
      "feedback": "Use \"es\" because being friendly is considered a permanent personality trait here."
    }
  ]
}

